import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.DSQXGnvq.js";const u=JSON.parse('{"title":"相关项目","description":"","frontmatter":{},"headers":[],"relativePath":"related-projects.md","filePath":"related-projects.md"}'),l={name:"related-projects.md"};function o(h,a,n,p,s,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="相关项目" tabindex="-1">相关项目 <a class="header-anchor" href="#相关项目" aria-label="Permalink to &quot;相关项目&quot;">​</a></h1><h2 id="原理图编辑器" tabindex="-1">原理图编辑器 <a class="header-anchor" href="#原理图编辑器" aria-label="Permalink to &quot;原理图编辑器&quot;">​</a></h2><p><a href="https://kicad-pcb.org" target="_blank" rel="noreferrer">KiCad</a> 是一个开源的电子设计自动化（EDA）软件套件，支持原理图捕获和 PCB 布局功能（可输出 Gerber 文件）。该套件运行于 Windows、Linux 和 macOS，基于 GNU GPL v3 协议。</p><h2 id="网表工具" tabindex="-1">网表工具 <a class="header-anchor" href="#网表工具" aria-label="Permalink to &quot;网表工具&quot;">​</a></h2><h3 id="skidl" tabindex="-1">SKiDL <a class="header-anchor" href="#skidl" aria-label="Permalink to &quot;SKiDL&quot;">​</a></h3><p><a href="https://devbisme.github.io/skidl/" target="_blank" rel="noreferrer">SKiDL</a> 是一个 Python 模块，可以用简洁的方式描述电子电路和元器件的互连。生成的 Python 程序会执行电气规则检查，并输出网表供 PCB 布局工具（如 KiCad）使用。</p><p>SKiDL 可以使用 PySpice API 生成电路，参考完整示例：<a href="https://github.com/devbisme/skidl" target="_blank" rel="noreferrer">https://github.com/devbisme/skidl</a></p><h2 id="电路模拟器" tabindex="-1">电路模拟器 <a class="header-anchor" href="#电路模拟器" aria-label="Permalink to &quot;电路模拟器&quot;">​</a></h2><h3 id="ahkab" tabindex="-1">Ahkab <a class="header-anchor" href="#ahkab" aria-label="Permalink to &quot;Ahkab&quot;">​</a></h3><p><a href="https://ahkab.github.io/ahkab" target="_blank" rel="noreferrer">Ahkab</a> 是一个用 Python 编写的类 SPICE 电子电路模拟器。</p><h3 id="lcapy" tabindex="-1">Lcapy <a class="header-anchor" href="#lcapy" aria-label="Permalink to &quot;Lcapy&quot;">​</a></h3><p><a href="http://lcapy.elec.canterbury.ac.nz" target="_blank" rel="noreferrer">Lcapy</a> 是一个用于线性电路分析的 Python 包。Lcapy 使用 SymPy 进行符号分析，可半自动地从网表生成原理图（使用 Circuitikz）。源码见 <a href="https://github.com/mph-/lcapy" target="_blank" rel="noreferrer">https://github.com/mph-/lcapy</a></p><h3 id="其他项目" tabindex="-1">其他项目 <a class="header-anchor" href="#其他项目" aria-label="Permalink to &quot;其他项目&quot;">​</a></h3><ul><li><a href="http://www.thedigitalmachine.net/eispice.html" target="_blank" rel="noreferrer">eispice</a></li><li><a href="http://www.spiceopus.si" target="_blank" rel="noreferrer">SPICE OPUS</a> 和 <a href="http://fides.fe.uni-lj.si/pyopus" target="_blank" rel="noreferrer">PyOPUS</a></li><li><a href="http://ieeexplore.ieee.org/xpl/login.jsp?tp=&amp;arnumber=5595224&amp;url=http%3A%2F%2Fieeexplore.ieee.org%2Fxpls%2Fabs_all.jsp%3Farnumber%3D5595224" target="_blank" rel="noreferrer">A Python interface for SPICE-based simulations</a></li></ul><h2 id="cpu-模拟器" tabindex="-1">CPU 模拟器 <a class="header-anchor" href="#cpu-模拟器" aria-label="Permalink to &quot;CPU 模拟器&quot;">​</a></h2><h3 id="pycpusimulator" tabindex="-1">PyCpuSimulator <a class="header-anchor" href="#pycpusimulator" aria-label="Permalink to &quot;PyCpuSimulator&quot;">​</a></h3><p><a href="https://github.com/FabriceSalvaire/PyCpuSimulator" target="_blank" rel="noreferrer">PyCpuSimulator</a> 是一个用 Python 编写的 CPU 模拟器，特点包括：</p><ul><li>微码语言描述指令</li><li>使用决策树的操作码解码器</li><li>读取 HEX 固件格式</li><li>AVR Core CPU 仿真（未完成）</li></ul>',18)])])}const b=e(l,[["render",o]]);export{u as __pageData,b as default};
